'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={bookmarks:[],notes:{},theme:'light'},storageAvailable=true;
try{const raw=JSON.parse(localStorage.getItem('scripture-lens-v1')||'{}');state={...state,...raw};if(!Array.isArray(state.bookmarks)||typeof state.notes!=='object'||state.notes===null)throw Error();state.bookmarks=state.bookmarks.filter(id=>ENTRIES.some(e=>e.id===id));}catch{state={bookmarks:[],notes:{},theme:'light'};}
let activeType='All studies',current=null,tab='passages',edition='KJV',toastTimer,view='explore';
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function persist(){try{localStorage.setItem('scripture-lens-v1',JSON.stringify(state))}catch{storageAvailable=false;toast('Browser storage unavailable. Export to keep your work.')}}
function applyTheme(){document.body.classList.toggle('dark',state.theme==='dark');$('#theme').setAttribute('aria-pressed',String(state.theme==='dark'))}applyTheme();
function corpus(e){return [e.title,e.type,e.topic,e.refs.join(' '),e.intro,e.claim,e.response,e.assessment,e.context,e.translation,...e.passages.flat()].join(' ').toLowerCase()}
function matches(e,q){return q.trim().toLowerCase().split(/\s+/).filter(Boolean).every(word=>corpus(e).includes(word))}
function card(e){let saved=state.bookmarks.includes(e.id);return `<article class="card" data-type="${esc(e.type)}"><div class="card-top"><span class="tag">${esc(e.type)}</span><button class="bookmark ${saved?'saved':''}" data-bookmark="${e.id}" aria-label="${saved?'Remove bookmark for':'Bookmark'} ${esc(e.title)}" aria-pressed="${saved}">${saved?'◆':'◇'}</button></div><h3><button data-open="${e.id}">${esc(e.title)}</button></h3><p>${esc(e.intro)}</p><div class="card-bottom"><span>${esc(e.refs[0])}<br>${esc(e.refs[1])}</span><button class="open-study" data-open="${e.id}">Examine ↗</button></div></article>`}
function renderCards(){const q=$('#search').value,t=$('#testament').value;const list=ENTRIES.filter(e=>matches(e,q)&&(activeType==='All studies'||e.type===activeType)&&(t==='All testaments'||e.testament===t||e.testament==='Both'));$('#cards').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>No matching studies.</h3><p>Try a broader term or reset the filters. This starter contains six studies.</p></div>';$('#results-count').textContent=`${list.length} ${list.length===1?'study':'studies'} in this collection`;const saved=ENTRIES.filter(e=>state.bookmarks.includes(e.id)||state.notes[e.id]);$('#saved-cards').innerHTML=saved.length?saved.map(card).join(''):'<div class="empty"><h3>A little room to think.</h3><p>Bookmark a study or write a note to add it to your desk.</p><button class="primary" data-view="explore">Explore the collection →</button></div>';$('#save-count').textContent=saved.length;}
function renderFilters(){$('#filters').innerHTML=['All studies',...Object.keys(TYPES)].map(t=>`<button class="chip ${t===activeType?'active':''}" data-filter="${esc(t)}" aria-pressed="${t===activeType}">${esc(t)}</button>`).join('')}renderFilters();renderCards();
$('#taxonomy').innerHTML=Object.entries(TYPES).map(([k,v])=>`<div class="taxonomy-item"><b>${esc(k)}</b>${esc(v)}</div>`).join('');
function setView(v,update=true){view=['explore','saved','method'].includes(v)?v:'explore';for(const name of ['explore','saved','method'])$(`#${name}-view`).hidden=name!==view;document.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(update)history.replaceState(null,'',`#${view}`);}
function bookmark(id){if(state.bookmarks.includes(id))state.bookmarks=state.bookmarks.filter(x=>x!==id);else state.bookmarks.push(id);persist();renderCards();if(current?.id===id){const b=$('#study-bookmark');if(b)b.textContent=state.bookmarks.includes(id)?'Bookmarked ◆':'Bookmark ◇'}toast(state.bookmarks.includes(id)?'Added to your research desk':'Bookmark removed')}
function contextUrl(ref,ed=edition){return `https://www.biblegateway.com/passage/?search=${encodeURIComponent(ref.replace(/:\d+$/,''))}&version=${ed}`}
function workspace(){const e=current;if(!e)return;$('#study-content').innerHTML=`<div class="study-heading"><div><span class="tag">${esc(e.type)}</span><h2>${esc(e.title)}</h2><p>${esc(e.intro)}</p></div><div class="study-actions"><button id="study-bookmark" class="secondary">${state.bookmarks.includes(e.id)?'Bookmarked ◆':'Bookmark ◇'}</button><button id="share" class="secondary">Copy link ↗</button><button id="export-study" class="secondary">Export ↓</button></div></div><div class="workspace-tools"><div class="tabs" role="tablist" aria-label="Study sections">${['passages','perspectives','sources','notes'].map(t=>`<button role="tab" id="tab-${t}" aria-controls="tab-content" aria-selected="${tab===t}" class="${tab===t?'active':''}" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div><label>Edition <select id="edition"><option ${edition==='KJV'?'selected':''}>KJV</option><option ${edition==='ASV'?'selected':''}>ASV</option><option ${edition==='Side by side'?'selected':''}>Side by side</option></select></label> <button id="font-size" class="secondary" aria-label="Increase passage text size">A+</button></div></div><div id="tab-content" role="tabpanel" aria-labelledby="tab-${tab}"></div>`;renderTab();$('#study-bookmark').onclick=()=>bookmark(e.id);$('#share').onclick=async()=>{const url=new URL(location.href);url.hash=`study/${e.id}`;try{await navigator.clipboard.writeText(url.href);toast('Study link copied. Your notes stay private.')}catch{const area=document.createElement('textarea');area.value=url.href;$('#tab-content').prepend(area);area.select();toast('Select and copy the displayed link.')}};$('#export-study').onclick=()=>download(`${e.id}-study.md`,studyMarkdown(e),'text/markdown');$('#edition').onchange=ev=>{edition=ev.target.value;renderTab()};$('#font-size').onclick=()=>{const currentSize=parseInt(document.documentElement.style.getPropertyValue('--reading-size')||'21');document.documentElement.style.setProperty('--reading-size',`${currentSize>=27?21:currentSize+2}px`)};}
function renderTab(){const e=current,box=$('#tab-content');if(tab==='passages'){const editions=edition==='Side by side'?['KJV','ASV']:[edition];box.innerHTML=`<div class="passages">${e.passages.map(p=>editions.map(ed=>`<article class="passage"><h3>${esc(p[0])} · ${ed}${e.id==='animals'&&p[0]==='Genesis 2:19'?' · excerpt':''}</h3><blockquote>${esc(p[ed==='KJV'?1:2])}</blockquote><a href="${contextUrl(p[0],ed)}" target="_blank" rel="noopener">Read full chapter context ↗</a></article>`).join('')).join('')}</div><div class="assessment"><div class="eyebrow">CONTEXT & TRANSLATION · PROVISIONAL EDITORIAL NOTES</div><p>${esc(e.context)}</p><p>${esc(e.translation)}</p></div>`}
if(tab==='perspectives')box.innerHTML=`<div class="analysis-grid"><article class="analysis-box original"><div class="eyebrow">ORIGINAL SOURCE · STEVE WELLS / SAB</div><h3>The skeptical annotation</h3>${e.original?`<blockquote>“${esc(e.original)}”</blockquote><p>Unaltered excerpt from the original source.</p>`:'<p>The full original annotation is available at the linked source. No verbatim excerpt is reproduced here.</p>'}<a href="${e.sab}" target="_blank" rel="noopener">Read the original SAB entry ↗</a><p><b>Editorial summary:</b> ${esc(e.claim)}</p></article><article class="analysis-box"><div class="eyebrow">${e.responseUrl?'ATTRIBUTED RESPONSE · GOTQUESTIONS':'POSSIBLE RESPONSE · EDITORIAL READING'}</div><h3>A competing reading</h3><p>${esc(e.response)}</p>${e.responseUrl?`<a href="${e.responseUrl}" target="_blank" rel="noopener">Read the complete response ↗</a><p>Confessional Christian interpretation; not independent historical corroboration.</p>`:'<p>No external response source attached. Treat this as a question to investigate.</p>'}</article></div><div class="assessment"><div class="eyebrow">EVIDENCE & LIMITS · PROVISIONAL EDITORIAL ANALYSIS</div><p>${esc(e.assessment)}</p><p><b>Research question:</b> ${esc(e.question)}</p><p><b>Classification:</b> ${esc(TYPES[e.type])}</p></div>`;
if(tab==='sources')box.innerHTML=`<div class="source-row"><a href="${e.sab}" target="_blank" rel="noopener">Skeptic’s Annotated Bible — Steve Wells ↗</a><p>Original skeptical source. Linked, separately attributed. Source checked October 11, 2026.</p></div>${e.responseUrl?`<div class="source-row"><a href="${e.responseUrl}" target="_blank" rel="noopener">GotQuestions — Christian response ↗</a><p>Theological/apologetic source. Response summarized separately. Checked October 11, 2026.</p></div>`:''}${e.refs.map(ref=>`<div class="source-row"><a href="${contextUrl(ref,'KJV')}" target="_blank" rel="noopener">${esc(ref)} — full KJV chapter ↗</a> · <a href="${contextUrl(ref,'ASV')}" target="_blank" rel="noopener">ASV chapter ↗</a><p>Primary text for the textual claim. Not independent evidence that a described event occurred.</p></div>`).join('')}<div class="assessment"><div class="eyebrow">EDITORIAL STATUS</div><p>Starter study · provisional classification · not scholarly reviewed. No peer-reviewed historical source or scholarly consensus is asserted in this record. Additional research should be attributed and reviewed before publication.</p></div>`;
if(tab==='notes'){box.innerHTML=`<label for="study-note"><h3>Your private research notes</h3></label><p class="notes-caption">Saved in this browser as you type. Export to preserve them elsewhere.</p><textarea class="notes-area" id="study-note" placeholder="What does the text establish? What assumptions still need evidence?">${esc(state.notes[e.id]||'')}</textarea><p class="notes-caption" id="note-status">${storageAvailable?'Browser-local storage':'Storage unavailable. Export your notes.'}</p>`;$('#study-note').oninput=ev=>{state.notes[e.id]=ev.target.value;persist();renderCards();$('#note-status').textContent=storageAvailable?'Saved in this browser':'Storage unavailable. Export your notes.'};}}
function openStudy(id,update=true){const e=ENTRIES.find(e=>e.id===id);if(!e)return;current=e;tab='passages';workspace();if(!$('#study-dialog').open)$('#study-dialog').showModal();if(update)history.replaceState(null,'',`#study/${id}`);$('#close-dialog').focus();}
$('#close-dialog').onclick=()=>$('#study-dialog').close();$('#study-dialog').addEventListener('close',()=>{history.replaceState(null,'',`#${view}`);current=null});$('#study-dialog').addEventListener('click',ev=>{if(ev.target===$('#study-dialog')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close()}});
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.open)openStudy(b.dataset.open);if(b.dataset.bookmark)bookmark(b.dataset.bookmark);if(b.dataset.filter){activeType=b.dataset.filter;renderFilters();renderCards()}if(b.dataset.view){setView(b.dataset.view);window.scrollTo({top:0,behavior:'smooth'})}if(b.dataset.tab){tab=b.dataset.tab;workspace();$(`#tab-${tab}`).focus()}});
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#study-dialog').open){ev.preventDefault();setView('explore');$('#search').focus()}if(ev.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight'].includes(ev.key)){ev.preventDefault();const tabs=['passages','perspectives','sources','notes'];tab=tabs[(tabs.indexOf(tab)+(ev.key==='ArrowRight'?1:3))%4];workspace();$(`#tab-${tab}`).focus()}});
$('#search').oninput=renderCards;$('#testament').onchange=renderCards;$('#reset').onclick=()=>{$('#search').value='';$('#testament').value='All testaments';activeType='All studies';renderFilters();renderCards()};$('#featured').onclick=()=>openStudy('seen');$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme();persist()};
$('#evidence-form').onsubmit=ev=>{ev.preventDefault();const q=$('#evidence-query').value.trim();const stop=new Set(['how','did','does','is','a','the','was','what','can','do','of','in','to','and','it','why','when','were','there','god']);let words=q.toLowerCase().replace(/[^a-z0-9\s:]/g,' ').split(/\s+/).filter(w=>w&&!stop.has(w));if(!words.length)words=q.toLowerCase().split(/\s+/).filter(Boolean);const ranked=ENTRIES.map(e=>({e,score:words.filter(w=>corpus(e).includes(w)).length})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,4);$('#evidence-results').innerHTML=ranked.length?`<div class="eyebrow">MATCHING RECORDS · RETRIEVAL, NOT A GENERATED ANSWER</div>${ranked.map(({e})=>`<article class="evidence-result"><button data-open="${e.id}">${esc(e.title)} ↗</button><p>${esc(e.claim)}</p><a href="${e.sab}" target="_blank" rel="noopener">Original SAB source ↗</a></article>`).join('')}`:'<p>No relevant records in this six-study collection. Try “Judas,” “census,” “plants,” or a passage reference.</p>'};
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded')}
function studyMarkdown(e){return `# ${e.title}\n\nClassification: ${e.type} (provisional editorial)\n\n${e.intro}\n\n## Passage extracts\n${e.passages.map(p=>`\n### ${p[0]} — KJV\n${p[1]}\n\n### ${p[0]} — ASV\n${p[2]}\n`).join('')}\n## Original SAB source\n${e.sab}\n${e.original?`\nSteve Wells, unaltered excerpt: “${e.original}”\n`:''}\nEditorial summary: ${e.claim}\n\n## Competing reading\n${e.response}\n${e.responseUrl||'No external source attached; proposed editorial reading.'}\n\n## Evidence and limits\n${e.assessment}\n\nResearch question: ${e.question}\n\n## My private notes\n${state.notes[e.id]||'(No notes)'}\n\nProvisional starter study. Not scholarly reviewed. Source check: October 11, 2026.\n`}
$('#export-all').onclick=()=>{const list=ENTRIES.filter(e=>state.bookmarks.includes(e.id)||state.notes[e.id]);if(!list.length){toast('Bookmark a study or add a note first');return}download('scripture-lens-research.md',list.map(studyMarkdown).join('\n\n---\n\n'),'text/markdown')};$('#export-backup').onclick=()=>download('scripture-lens-backup.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2),'application/json');
$('#import-backup').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Backup exceeds 2 MB');const backup=JSON.parse(await file.text());if(backup.version!==1||!Array.isArray(backup.bookmarks)||!backup.notes||typeof backup.notes!=='object'||Array.isArray(backup.notes))throw Error('Not a Scripture Lens backup');const valid=ENTRIES.map(e=>e.id);state.bookmarks=[...new Set([...state.bookmarks,...backup.bookmarks.filter(id=>valid.includes(id))])];for(const id of valid){const note=backup.notes[id];if(typeof note==='string'&&note.length<=100000){const old=state.notes[id];state.notes[id]=old&&old!==note?`${old}\n\n--- Imported note ---\n${note}`:note}}persist();renderCards();$('#backup-status').textContent='Backup restored. Existing notes were preserved.'}catch(err){$('#backup-status').textContent=`Could not restore: ${err.message}`}ev.target.value=''};
function route(){const hash=decodeURIComponent(location.hash.slice(1));if(hash.startsWith('study/')){setView('explore',false);const id=hash.slice(6);if(ENTRIES.some(e=>e.id===id))openStudy(id,false);else toast('Study not found in this collection')}else setView(hash,false)}window.addEventListener('hashchange',route);route();
